/*

Thanks FabriceNeyret2.
Great idea for a puzzle game.
Simple idea that makes very difficult puzzles.

Keyboard commands:

<Arrow keys>  roll the puzzle.
<Shift> + <Arrow keys> move the pivot point.
<Space> toggles display style (picture versus color map).

Set XSIZE,YSIZE in common tab to adjust puzzle resolution. 
Set channel1 to a harder texture image or to video if you want to go crazy.

*/

void sdfCircle(vec2 pt, float radius, vec3 color,inout vec4 O, vec2 U) {
    float d = length(U - pt);
    if(d < radius) {
        float d2 = length(U - vec2(-radius * 0.3,radius * 0.3) - pt);
        O.xyz = color - vec3(d2 / (radius * 3.5));
    }

    if(abs(d - radius) < 1.) O.xyz = vec3(1.);
}

vec3 jetColorMap(float t) { // 0 ... 1
    return clamp(vec3(1.5) - abs(4.0 * vec3(t) + vec3(-3., -2., -1.)), vec3(0.), vec3(1.));
}

// ------------------------------------------------

void mainImage(out vec4 O, vec2 U) {
    loadData(iChannel0);

    vec2 cellSize = iResolution.xy / vec2(XSIZE,YSIZE);
    ivec2 pic = ivec2(U / cellSize);
    ivec2 src = q[map(pic)].xy;
    vec2 piece = U + vec2(src-pic) * cellSize;

    if(qStyle == 0)
        O = textureLod(iChannel1,piece/iResolution.xy,0.);
    else 
        O.xyz = jetColorMap((piece.x/iResolution.x  + piece.y/iResolution.y) * 0.5);

    // grid lines
    for(int x=1;x<XSIZE;++x) 
        if(abs(U.x - cellSize.x * float(x)) < 1.) O.xyz = vec3(0.0);
    for(int y=0;y<YSIZE;++y)
        if(abs(U.y - cellSize.y * float(y)) < 1.) O.xyz = vec3(0.0);

    // pivot symbol
    vec2 pivot = vec2(qPivot) * cellSize + cellSize * 0.5;
    sdfCircle(pivot,5. + iResolution.x/200.,vec3(1.,0.,0.),O,U);
}

const int XSIZE = 4;      // # pieces per axis
const int YSIZE = 4;

#define qPivot  q[0].xy   // slider pivot cell position
#define qStyle  q[0].z    // display style code

const int QBASE = 1;      // board storage starting index
const int QSIZE = QBASE + XSIZE*YSIZE; // total storage

ivec4 q[QSIZE];

int map(ivec2 cell) { return QBASE + cell.y * XSIZE + cell.x; } // cell storage location

void loadData(sampler2D channel) {
    for(int i=0;i<QSIZE;++i) 
        q[i] = ivec4(texelFetch(channel,ivec2(i,0),0));
}

void saveData(inout vec4 O,vec2 U) {
    ivec2 I = ivec2(U);    
    if(I.y == 0 && I.x < QSIZE) 
        O = vec4(q[I.x]);
}

// --------------------------------------------------------
// keyboard: https://www.shadertoy.com/view/lsXGzf

const int KEY_LEFT  = 37;
const int KEY_UP    = 38;
const int KEY_RIGHT = 39;
const int KEY_DOWN  = 40;
const int KEY_SHIFT  = 16;

bool getKeyState(int keyCode){
    return bool(texelFetch(iChannel2, ivec2(keyCode,0), 0).x != 0.);
}

bool getKeyClick(int keyCode){
    return bool(texelFetch(iChannel2, ivec2(keyCode,1), 0).x != 0.);
}

// ----------------------------------------------------------

vec2 rseed = vec2(12.9898, 78.233);

int iRandom(int max) { // 0...max-1
    rseed.xy += iTime * iDate.zw;
    float v = sin(dot(rseed, vec2(12.9898, 78.233))) * 43758.5453;
	return int(float(max) * fract(v));
}

// ----------------------------------------------------------

void newGame(inout vec4 O, vec2 U) {
    qPivot = ivec2(XSIZE,YSIZE) / 2;

    for(int x=0;x<XSIZE;++x) // unscrambled initial positions
        for(int y=0;y<YSIZE;++y) 
            q[map(ivec2(x,y))].xy = ivec2(x,y);

    for(int i=0;i<100;++i) { // scramble
        int i1 = map(ivec2(iRandom(XSIZE),iRandom(YSIZE)));
        int i2 = map(ivec2(iRandom(XSIZE),iRandom(YSIZE)));
        ivec2 t = q[i1].xy;
        q[i1].xy = q[i2].xy;
        q[i2].xy = t;
    }

    saveData(O,U);
}

// ----------------------------------------------------------

void roll(int dx,int dy,inout vec4 O, vec2 U) {
    if(dx < 0) {
        ivec2 t = q[map(ivec2(0,qPivot.y))].xy;
        for(int i=0;i<XSIZE-1;++i) 
            q[map(ivec2(i,qPivot.y))].xy = q[map(ivec2(i+1,qPivot.y))].xy;
        q[map(ivec2(XSIZE-1,qPivot.y))].xy = t;
    }
    if(dx > 0) {
        ivec2 t = q[map(ivec2(XSIZE-1,qPivot.y))].xy;
        for(int i=XSIZE-1;i>=1;--i) 
            q[map(ivec2(i,qPivot.y))].xy = q[map(ivec2(i-1,qPivot.y))].xy;
        q[map(ivec2(0,qPivot.y))].xy = t;
    }
    if(dy < 0) {
        ivec2 t = q[map(ivec2(qPivot.x,0))].xy;
        for(int i=0;i<YSIZE-1;++i) 
            q[map(ivec2(qPivot.x,i))].xy = q[map(ivec2(qPivot.x,i+1))].xy;
        q[map(ivec2(qPivot.x,YSIZE-1))].xy = t;
    }
    if(dy > 0) {
        ivec2 t = q[map(ivec2(qPivot.x,YSIZE-1))].xy;
        for(int i=YSIZE-1;i>=1;--i) 
            q[map(ivec2(qPivot.x,i))].xy = q[map(ivec2(qPivot.x,i-1))].xy;
        q[map(ivec2(qPivot.x,0))].xy = t;
    }
}

// ----------------------------------------------------------

void mainImage(out vec4 O, vec2 U) {
    if(U.x > float(QSIZE) || U.y > 1.0) return; 

    if(iFrame < 2) {
        qStyle  = 0;
        newGame(O,U);
        return;
    }

    loadData(iChannel0);

    if(getKeyState(KEY_SHIFT)) { // move pivot point
        if(getKeyClick(KEY_LEFT))  qPivot.x = (qPivot.x + XSIZE- 1) % XSIZE;
        if(getKeyClick(KEY_RIGHT)) qPivot.x = (qPivot.x + XSIZE+ 1) % XSIZE;
        if(getKeyClick(KEY_DOWN))  qPivot.y = (qPivot.y + YSIZE- 1) % YSIZE;
        if(getKeyClick(KEY_UP))    qPivot.y = (qPivot.y + YSIZE+ 1) % YSIZE;
    } else { 
        if(getKeyClick(KEY_LEFT))  roll(-1,0,O,U);
        if(getKeyClick(KEY_RIGHT)) roll(+1,0,O,U);
        if(getKeyClick(KEY_DOWN))  roll(0,-1,O,U);
        if(getKeyClick(KEY_UP))    roll(0,+1,O,U);
    }

    if(getKeyClick(32)) qStyle = 1 - qStyle;

    saveData(O,U);
}
